<script setup lang="ts">
import { nextTick,onBeforeUnmount,onMounted,ref,shallowRef,watch } from 'vue'
import { GameEngine } from '@/engine/GameEngine'
import { useControls } from '@/composables/useControls'
import { useHudStore } from '@/stores/hud'
import { settings } from '@/stores/profile'
import type { IUpgrade,ScreenState,WeaponKind } from '@/types/game'
import HudOverlay from '@/components/hud/HudOverlay.vue'
import VirtualControls from '@/components/hud/VirtualControls.vue'
import UpgradeMenu from '@/components/hud/UpgradeMenu.vue'
import GameOverlay from '@/components/GameOverlay.vue'
import Lobby from '@/components/Lobby.vue'
const canvas=ref<HTMLCanvasElement|null>(null),screen=ref<ScreenState>('menu'),upgrades=shallowRef<readonly IUpgrade[]>([]),ready=ref(false),muted=ref(false),notice=ref('');const controls=useControls(),hud=useHudStore();let engine:GameEngine|null=null;let noticeTimer:ReturnType<typeof setTimeout>|undefined
const focus=()=>void nextTick(()=>canvas.value?.focus({preventScroll:true}));const start=()=>{if(!ready.value)return;controls.clear();engine?.start();focus()};const pause=()=>{engine?.togglePause();if(screen.value==='playing')focus()};const choose=(u:IUpgrade)=>{engine?.chooseUpgrade(u);focus()};const weapon=(w:WeaponKind)=>{controls.queueWeapon(w);focus()};const menu=()=>{engine?.returnToMenu();upgrades.value=[]};const sound=()=>{muted.value=!muted.value;engine?.setMuted(muted.value)};const configure=()=>engine?.configure();const showNotice=(s:string)=>{notice.value=s;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>notice.value='',5000)}
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else showNotice('La pantalla completa no está disponible en este navegador.')}catch{showNotice('La vista previa no permite pantalla completa. Puedes jugar normalmente.')}}
const key=(e:KeyboardEvent)=>{if(e.repeat||e.isComposing)return;if(document.querySelector('[role="dialog"],dialog[open]')&&screen.value!=='paused')return;if(e.target instanceof HTMLElement&&e.target.closest('input,select,textarea'))return;const k=e.key.toLowerCase();if(k==='p'||k==='escape'){e.preventDefault();pause()}if(k==='enter'&&screen.value==='menu'&&!(e.target instanceof HTMLButtonElement)){e.preventDefault();start()}if(k==='q'&&screen.value==='playing')engine?.cycleWeapon()};const visibility=()=>{if(document.hidden&&screen.value==='playing')pause()};const resize=()=>engine?.resize();const pointer=(e:PointerEvent)=>{if(screen.value!=='playing'||e.pointerType!=='mouse')return;controls.state.aimX=e.clientX-window.innerWidth/2;controls.state.aimY=e.clientY-window.innerHeight/2+24;controls.state.aiming=true};const down=(e:PointerEvent)=>{if(e.pointerType!=='mouse')return;pointer(e);canvas.value?.setPointerCapture(e.pointerId);controls.state.firing=true};const up=()=>{controls.state.firing=false}
const actions={dog:(o:string)=>engine?.setDogOrder(o),reload:()=>engine?.reload(),cycle:()=>engine?.cycleWeapon(),squad:()=>engine?.summonSquad()}
watch(settings,configure,{deep:true})
onMounted(()=>{if(!canvas.value)return;try{engine=new GameEngine(canvas.value,controls.state,{onHud:hud.publish,onScreen:n=>{screen.value=n;if(n!=='playing')controls.clear()},onUpgrades:n=>upgrades.value=n});ready.value=true}catch(e){showNotice('No se pudo iniciar el juego. Canvas2D requiere un navegador compatible.');console.error(e)}window.addEventListener('resize',resize);window.addEventListener('keydown',key);document.addEventListener('visibilitychange',visibility);document.addEventListener('fullscreenchange',resize)})
onBeforeUnmount(()=>{window.removeEventListener('resize',resize);window.removeEventListener('keydown',key);document.removeEventListener('visibilitychange',visibility);document.removeEventListener('fullscreenchange',resize);clearTimeout(noticeTimer);engine?.dispose()})
</script>
<template><main class="game-shell" :data-screen="screen" :data-ready="ready" data-testid="app-shell"><canvas ref="canvas" class="game-canvas" data-testid="game-canvas" tabindex="0" aria-label="Dead City, juego de supervivencia zombi" @pointermove="pointer" @pointerdown="down" @pointerup="up" @pointercancel="up" @lostpointercapture="up"/><Lobby v-if="screen==='menu'" :ready="ready" :muted="muted" @start="start" @sound="sound" @fullscreen="fullscreen" @configure="configure"/><template v-if="screen==='playing'"><HudOverlay :state="hud.state.value" :muted="muted" @weapon="weapon" @pause="pause" @sound="sound" @dog="actions.dog"/><VirtualControls :state="hud.state.value" @move="controls.setJoystick" @release="controls.releaseJoystick" @aim="controls.setAim" @aimrelease="controls.releaseAim" @fire="v=>controls.state.firing=v" @pulse="controls.queuePulse" @reload="actions.reload" @cycle="actions.cycle" @squad="actions.squad"/></template><UpgradeMenu v-if="screen==='levelup'" :upgrades="upgrades" :level="hud.state.value.level" @choose="choose"/><GameOverlay :screen="screen" :state="hud.state.value" @start="start" @resume="pause" @menu="menu" @configure="configure"/><div v-if="notice" class="notice" role="status">{{notice}}</div></main></template>
